"""Move a cloud of particles under mutual gravity on the GPU and summarize them.

Usage: uv run main.py <input-file>
"""

import math
import sys

import numpy as np
import wgpu

WORKGROUP = 64

# Part 1 of a step: every acceleration from the positions the step started
# with, folded straight into the velocity. Positions are only read here.
ACCEL_SHADER = f"""
struct Params {{ count: u32, dt: f32, }};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;

@compute @workgroup_size({WORKGROUP})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {{
    let i = gid.x;
    if (i >= params.count) {{ return; }}
    let pi = pos[i];
    var acc = vec2<f32>(0.0, 0.0);
    for (var j: u32 = 0u; j < params.count; j = j + 1u) {{
        if (j == i) {{ continue; }}
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        acc = acc + d / (r2 * sqrt(r2));
    }}
    vel[i] = vel[i] + acc * params.dt;
}}
"""

# Part 2 of a step: positions advance by the new velocities.
MOVE_SHADER = f"""
struct Params {{ count: u32, dt: f32, }};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read> vel: array<vec2<f32>>;

@compute @workgroup_size({WORKGROUP})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {{
    let i = gid.x;
    if (i >= params.count) {{ return; }}
    pos[i] = pos[i] + vel[i] * params.dt;
}}
"""


def parse(path):
    with open(path) as f:
        tokens = f.read().split()
    count = int(float(tokens[0]))
    steps = int(float(tokens[1]))
    dt = float(tokens[2])
    fields = np.array([float(t) for t in tokens[3 : 3 + 4 * count]], dtype=np.float64)
    if fields.size != 4 * count:
        raise ValueError(f"expected {count} particles, got {fields.size / 4:g}")
    fields = fields.reshape(count, 4)
    return count, steps, dt, fields[:, 0:2].copy(), fields[:, 2:4].copy()


def get_device():
    adapter = None
    for kwargs in ({"power_preference": "high-performance"}, {"force_fallback_adapter": True}):
        try:
            adapter = wgpu.gpu.request_adapter_sync(**kwargs)
        except Exception:
            adapter = None
        if adapter is not None:
            break
    if adapter is None:
        raise RuntimeError("no GPU adapter available")
    return adapter.request_device_sync()


def simulate(pos, vel, steps, dt):
    """Run `steps` steps on the GPU; return float32 positions and velocities."""
    count = pos.shape[0]
    pos32 = np.ascontiguousarray(pos, dtype=np.float32)
    vel32 = np.ascontiguousarray(vel, dtype=np.float32)
    if steps == 0:
        return pos32, vel32

    device = get_device()
    storage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    pos_buf = device.create_buffer_with_data(data=pos32.tobytes(), usage=storage)
    vel_buf = device.create_buffer_with_data(data=vel32.tobytes(), usage=storage)
    params = np.zeros(4, dtype=np.uint32)
    params[0] = count
    params[1:2] = np.array([dt], dtype=np.float32).view(np.uint32)
    param_buf = device.create_buffer_with_data(
        data=params.tobytes(), usage=wgpu.BufferUsage.UNIFORM
    )

    def pipeline(code, pos_type, vel_type):
        layout = device.create_bind_group_layout(
            entries=[
                {"binding": 0, "visibility": wgpu.ShaderStage.COMPUTE,
                 "buffer": {"type": wgpu.BufferBindingType.uniform}},
                {"binding": 1, "visibility": wgpu.ShaderStage.COMPUTE,
                 "buffer": {"type": pos_type}},
                {"binding": 2, "visibility": wgpu.ShaderStage.COMPUTE,
                 "buffer": {"type": vel_type}},
            ]
        )
        pipe = device.create_compute_pipeline(
            layout=device.create_pipeline_layout(bind_group_layouts=[layout]),
            compute={"module": device.create_shader_module(code=code), "entry_point": "main"},
        )
        group = device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": param_buf}},
                {"binding": 1, "resource": {"buffer": pos_buf}},
                {"binding": 2, "resource": {"buffer": vel_buf}},
            ],
        )
        return pipe, group

    ro = wgpu.BufferBindingType.read_only_storage
    rw = wgpu.BufferBindingType.storage
    accel = pipeline(ACCEL_SHADER, ro, rw)
    move = pipeline(MOVE_SHADER, rw, ro)
    groups = (count + WORKGROUP - 1) // WORKGROUP

    encoder = device.create_command_encoder()
    for _ in range(steps):
        for pipe, group in (accel, move):
            # A separate pass per dispatch keeps each kernel's writes ordered
            # before the next kernel's reads.
            cpass = encoder.begin_compute_pass()
            cpass.set_pipeline(pipe)
            cpass.set_bind_group(0, group)
            cpass.dispatch_workgroups(groups, 1, 1)
            cpass.end()
    device.queue.submit([encoder.finish()])

    out_pos = np.frombuffer(device.queue.read_buffer(pos_buf), dtype=np.float32).reshape(count, 2)
    out_vel = np.frombuffer(device.queue.read_buffer(vel_buf), dtype=np.float32).reshape(count, 2)
    return out_pos, out_vel


def fmt(x):
    s = f"{x:.6f}"
    return "0.000000" if s == "-0.000000" else s


def summarize(pos, vel):
    pos = pos.astype(np.float64)
    vel = vel.astype(np.float64)
    center = pos.mean(axis=0)
    momentum = vel.sum(axis=0)
    kinetic = float(((vel * vel).sum(axis=1) / 2).sum())
    spread = math.sqrt(float(((pos - center) ** 2).sum(axis=1).mean()))
    return [
        f"CENTER {fmt(center[0])} {fmt(center[1])}",
        f"MOMENTUM {fmt(momentum[0])} {fmt(momentum[1])}",
        f"KINETIC {fmt(kinetic)}",
        f"SPREAD {fmt(spread)}",
    ]


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    count, steps, dt, pos, vel = parse(argv[1])
    pos, vel = simulate(pos, vel, steps, dt)
    sys.stdout.write("\n".join(summarize(pos, vel)) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

